input.content:
'use server'

import { revalidatePath } from 'next/cache'

let notificationsEnabled = true

export async function getNotificationPreference() {
  return notificationsEnabled
}

export async function toggleNotificationPreference() {
  notificationsEnabled = !notificationsEnabled
  revalidatePath('/')
}

import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently: {enabled ? 'on' : 'off'}</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
